 ActivityScenario<MainActivity> scenario;MainActivity a;
 static String js(WebView v,String code)throws Exception{CountDownLatch l=new CountDownLatch(1);AtomicReference<String> result=new AtomicReference<>();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->v.evaluateJavascript(code,r->{result.set(r);l.countDown();}));assertTrue("WebView JavaScript callback timed out",l.await(15,TimeUnit.SECONDS));return result.get();}
 interface Check{boolean run()throws Exception;}
 static void until(Check c)throws Exception{long end=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<end){if(c.run())return;Thread.sleep(100);}fail("UI condition did not become true");}
 void ok(String code)throws Exception{assertEquals(code,"true",js(a.shell,code));}
 void run(String code)throws Exception{js(a.shell,code);}
 void openMenu()throws Exception{run("document.getElementById('menu').click()");ok("!document.getElementById('settings').hidden");}
 void shot(String name)throws Exception{Thread.sleep(250);ParcelFileDescriptor p=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand("screencap -p /sdcard/"+name+".png");try(java.io.InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){byte[] buf=new byte[1024];while(in.read(buf)!=-1){}}}
 @Before public void before()throws Exception{scenario=ActivityScenario.launch(MainActivity.class);scenario.onActivity(v->a=v);until(()->"true".equals(js(a.shell,"!!window.OSMINOG?.nativeReady")));run("document.getElementById('welcomeWake')?.click();document.getElementById('welcomeScreen')?.remove();records=[];pendingFile=null;attachmentPreview();localStorage.setItem('osminogPersonalOceanV1','[]');document.getElementById('text').value='';notice();render();setMenu(false);collapseSettings(true)");}
 @After public void after(){if(scenario!=null)scenario.close();}
