 @Test public void attachmentsAboveTwoMegabytesPersistAsBlobs()throws Exception{
  run("window.mediaDone=false;addMedia([new File([new Uint8Array(3000000)],'large.mp4',{type:'video/mp4'})]).then(async success=>{window.mediaDone=success&&(await MediaStore.get(pendingFile[0].id)).size===3000000})");
  until(()->"true".equals(js(a.shell,"window.mediaDone")));
  run("ask('Медиа');window.beforeMediaReload=true");
  ok("records[0].file.length===1&&!!records[0].file[0].id&&!records[0].file[0].data&&JSON.stringify(records).length<2000");
  scenario.onActivity(v->v.shell.reload());
  until(()->"true".equals(js(a.shell,"typeof window.beforeMediaReload==='undefined'&&!!window.OSMINOG?.nativeReady&&typeof MediaStore!=='undefined'")));
  ok("records.length===1&&records[0].file.length===1");
  run("window.restoredBlob='waiting';MediaStore.get(records[0].file[0].id).then(blob=>window.restoredBlob=blob?blob.size:'missing').catch(e=>window.restoredBlob=e.name)");
  until(()->!"\"waiting\"".equals(js(a.shell,"window.restoredBlob")));
  assertEquals("Persisted Blob size after a NEW WebView document", "3000000",js(a.shell,"window.restoredBlob"));
 }

